using System;using System.IO;using System.Drawing;using System.Diagnostics;using System.Windows.Forms;
internal sealed partial class ControlWindow {
 readonly CheckBox mute=new CheckBox();readonly TrackBar volume=new TrackBar();readonly Label volumeLabel=new Label();bool audioDirty;long audioSequence;readonly Stopwatch audioDelay=Stopwatch.StartNew();
 Control BuildAudioPanel(){var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=2,Margin=Padding.Empty};p.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,U(68)));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));p.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,U(28)));p.RowStyles.Add(new RowStyle(SizeType.Absolute,U(23)));p.RowStyles.Add(new RowStyle(SizeType.Percent,100));mute.Text="静音";mute.Checked=settings.Muted;mute.AutoSize=true;mute.Dock=DockStyle.Fill;p.Controls.Add(mute,0,0);p.Controls.Add(new Label{Text="壁纸声音",Dock=DockStyle.Fill,ForeColor=Muted,TextAlign=ContentAlignment.MiddleRight,Font=new Font(Font.FontFamily,8.5f)},1,0);p.SetColumnSpan(p.GetControlFromPosition(1,0),2);volume.Minimum=0;volume.Maximum=100;volume.TickStyle=TickStyle.None;volume.Value=settings.Volume;volume.Dock=DockStyle.Fill;volume.Margin=Padding.Empty;volumeLabel.Text=settings.Volume.ToString();volumeLabel.Dock=DockStyle.Fill;volumeLabel.Font=new Font(Font.FontFamily,8);p.Controls.Add(volume,0,1);p.SetColumnSpan(volume,2);p.Controls.Add(volumeLabel,2,1);mute.CheckedChanged+=(s,e)=>AudioChanged();volume.ValueChanged+=(s,e)=>AudioChanged();return p;}
 void AudioChanged(){settings.Muted=mute.Checked;settings.Volume=volume.Value;volumeLabel.Text=volume.Value.ToString();audioDirty=true;audioDelay.Restart();try{settings.Save();}catch(Exception ex){RecordFault("save","保存声音设置","settings-save",ex.Message);libraryHint.Text="声音设置未保存："+ex.Message;libraryHint.ForeColor=Color.Firebrick;}}
 void FlushAudio(){if(!audioDirty||audioDelay.ElapsedMilliseconds<400)return;audioDirty=false;if(CurrentRun==null||PlayerRole!="alive")return;try{Common.ReplaceJson(Path.Combine(CurrentRun,"audio-request.json"),new{token=runToken,sequence=++audioSequence,muted=settings.Muted,volume=settings.Volume});Write("audio-requested",new{muted=settings.Muted,volume=settings.Volume,sequence=audioSequence});}catch(Exception ex){libraryHint.Text="声音调整失败："+ex.Message;Write("audio-request-error",new{error=ex.Message});}}
}
